/* ---------- 公園 3 變化 ---------- */
SPR.park=[];
const mt=(g,x,y)=>{g.fillStyle='#6b4a2f';g.fillRect(x,y+5,2,4);
  g.fillStyle='#3d7a3c';g.fillRect(x-4,y-3,10,9);
  g.fillStyle='#4b8f45';g.fillRect(x-3,y-4,8,7);
  g.fillStyle='#63ad55';g.fillRect(x-2,y-3,4,4);};
for(let v=0;v<3;v++){const[c,g]=cv(64,56);
  const ay=53;
  dia(g,32,ay-32,32,'#82c163');
  speck(g,32,ay-32,32,['#6fae52','#95d276','#78b95c'],60,rand);
  diaEdge(g,9,'#90cc72',32,ay-32,32);
  diaEdge(g,6,'#74ad57',32,ay-32,32);
  if(v===2){                                          // 池塘
    dia(g,32,ay-26,12,'#4f93cf');
    dia(g,32,ay-24,8,'#6fb0e0');
    g.fillStyle='#bfe4f5';g.fillRect(30,ay-21,3,1);
    diaEdge(g,15,'#d9c689',32,ay-26,12);
    mt(g,14,ay-26);
  }else{
    g.fillStyle='#cbb98e';                            // 石徑
    for(let i=0;i<5;i++)g.fillRect(12+i*8,ay-20+((i%2)*2),5,2);
    mt(g,14,ay-28);mt(g,46,ay-24);
    if(v===0){
      g.fillStyle='#8a5f38';g.fillRect(38,ay-30,7,2);  // 長椅
      g.fillRect(38,ay-28,1,2);g.fillRect(44,ay-28,1,2);
      const fc=['#e8e070','#e8907e','#d9a8e8','#f2f2f2'];
      for(let i=0;i<8;i++){g.fillStyle=fc[ri(4)];g.fillRect(20+ri(20),ay-14+ri(5),2,1);}
    }
  }
  SPR.park.push({img:c,ax:32,ay:ay,w:64,h:56});}

